/* Transparent 3D-rendered combat sprites. Rendering never changes simulation data. */
(function(){'use strict';const C=Critters,R=CritterRenderer.prototype,oldWeapon=R.weapon,oldEvent=R.event,oldEffects=R.effects,oldSet=R.setGame;
const sheets={held:{image:new Image(),tiles:[],ready:false},shot:{image:new Image(),tiles:[],ready:false}};
function slice(sheet){const image=sheet.image,cw=image.naturalWidth/7,ch=image.naturalHeight/4,source=document.createElement('canvas');source.width=image.naturalWidth;source.height=image.naturalHeight;const ctx=source.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);for(let id=0;id<28;id++){const x=Math.floor(id%7*cw),y=Math.floor(Math.floor(id/7)*ch),width=Math.floor(cw),height=Math.floor(ch),pixels=ctx.getImageData(x,y,width,height).data;let left=width,right=-1,top=height,bottom=-1;const seen=new Uint8Array(width*height);let best=[];for(let n=0;n<seen.length;n++){if(seen[n]||pixels[n*4+3]<=18)continue;const part=[n];seen[n]=1;for(let j=0;j<part.length;j++){const q=part[j],px=q%width;for(const z of [px>0?q-1:-1,px<width-1?q+1:-1,q-width,q+width])if(z>=0&&z<seen.length&&!seen[z]&&pixels[z*4+3]>18){seen[z]=1;part.push(z);}}if(part.length>best.length)best=part;}for(const n of best){const px=n%width,py=Math.floor(n/width);left=Math.min(left,px);right=Math.max(right,px);top=Math.min(top,py);bottom=Math.max(bottom,py);}if(right<0){left=top=0;right=width-1;bottom=height-1;}left=Math.max(0,left-2);top=Math.max(0,top-2);right=Math.min(width-1,right+2);bottom=Math.min(height-1,bottom+2);const tile=document.createElement('canvas');tile.dataset.combatSprite=sheet.kind+':'+id;tile.width=right-left+1;tile.height=bottom-top+1;tile.getContext('2d').drawImage(image,x+left,y+top,tile.width,tile.height,0,0,tile.width,tile.height);sheet.tiles.push(tile);}sheet.ready=true;window.dispatchEvent(new Event('pc:combat-art-ready'));}
for(const [type,name]of [['held','combat-held.webp'],['shot','combat-shots.webp']]){const sheet=sheets[type];sheet.kind=type;sheet.image.onload=()=>slice(sheet);sheet.image.src=name;}
function model(k,type,id,x,y,w,h,angle=0){const tile=sheets[type]?.tiles[id];if(!tile)return false;const scale=Math.min(w/tile.width,h/tile.height);k.save();k.translate(x,y);k.rotate(angle);k.drawImage(tile,-tile.width*scale/2,-tile.height*scale/2,tile.width*scale,tile.height*scale);k.restore();return true;}
C.drawCombatModel=model;C.combatArtStatus=()=>({held:sheets.held.ready,shot:sheets.shot.ready,heldCount:sheets.held.tiles.length,shotCount:sheets.shot.tiles.length});
const held={0:[56,30,.12],2:[60,37,.1],5:[51,27,0],6:[58,34,.08],12:[64,28,.13],16:[55,55,.75],17:[50,43,0],18:[54,46,.65],20:[49,42,0]};
R.weapon=function(k,id,x,y,s=1){const spec=held[id]||[43,43,0];if(!model(k,'held',id,x,y,spec[0]*s,spec[1]*s,spec[2]))return oldWeapon.call(this,k,id,x,y,s);};
const directional=new Set([0,2,5,6,10,12,15,18,19,20]),spinning=new Set([1,4,7,9,11,21,22,23,25]);const sizes={0:[29,15],1:[23,27],2:[32,20],4:[27,27],5:[35,20],6:[15,9],7:[29,29],9:[34,37],10:[35,28],11:[35,27],12:[32,10],15:[39,24],18:[31,20],19:[35,27],20:[31,22],21:[38,38],22:[37,22],23:[34,34],24:[28,32],25:[29,31]};
R.drawProjectileSprite=function(k,p){if(!sheets.shot.ready)return false;const id=p.weapon,w=C.WEAPONS[id],spec=sizes[id]||[27,27],small=p.child?.58:1,trail=p.trail||[];k.save();if(!p.preview&&trail.length>1&&!this.reduced){k.lineCap='round';k.strokeStyle=w.color;k.lineWidth=p.child?1.4:[12,15,19].includes(id)?3:2;for(let i=1;i<trail.length;i++){k.globalAlpha=i/trail.length*.4;k.beginPath();k.moveTo(trail[i-1].x,trail[i-1].y);k.lineTo(trail[i].x,trail[i].y);k.stroke();}}k.globalAlpha=1;let angle=directional.has(id)?Math.atan2(p.vy,p.vx):spinning.has(id)&&!this.reduced?p.age*(id===22?8:2.8):0;if(p.stuck){this.combatStuck??=new WeakMap();if(!this.combatStuck.has(p))this.combatStuck.set(p,angle);angle=this.combatStuck.get(p);}if(!this.reduced&&[9,15,19,21,23].includes(id)){k.shadowColor=w.color;k.shadowBlur=id===9?9:6;}model(k,'shot',id,p.x,p.y,spec[0]*small,spec[1]*small,angle);k.shadowBlur=0;if(w.fuse&&!p.child&&!p.preview){k.fillStyle='#15253ee8';k.beginPath();k.roundRect(p.x-18,p.y-43,36,17,5);k.fill();k.font='bold 11px monospace';k.textAlign='center';k.fillStyle=w.color;k.fillText(Math.max(0,w.fuse-p.age).toFixed(1)+'s',p.x,p.y-31);}k.restore();return true;};
R.drawFlyingHook=function(k){return model(k,'shot',17,0,0,25,25,.5);};
R.setGame=function(...args){oldSet.apply(this,args);this.combatStuck=new WeakMap();this.combatSkillFx=[];};
R.event=function(e){oldEvent.call(this,e);let index=null;if(e.type==='heal')index=3;else if(e.type==='heroRevive')index=27;else if(e.type==='parasiteBurst')index=26;else if(e.type==='fire'&&[8,13,14].includes(e.weapon))index=e.weapon;if(index===null)return;const u=e.id!==undefined?this.game.units[e.id]:this.game.active;this.combatSkillFx??=[];if(this.combatSkillFx.length<12)this.combatSkillFx.push({index,x:e.x??u.x,y:(e.y??u.y)-50,life:.8,max:.8});};
R.effects=function(k,dt){oldEffects.call(this,k,dt);for(const fx of this.combatSkillFx||[]){if(!this.game.paused)fx.life-=dt;k.save();k.globalAlpha=Math.max(0,Math.min(1,fx.life/.25));const phase=1-fx.life/fx.max,scale=this.reduced?1:.85+Math.sin(phase*Math.PI)*.2;model(k,'shot',fx.index,fx.x,fx.y-(this.reduced?0:phase*14),45*scale,45*scale);k.restore();}this.combatSkillFx=(this.combatSkillFx||[]).filter(f=>f.life>0);};
const projectile=R.projectile;R.projectile=function(k){projectile.call(this,k);const r=this.game.rope;if(r&&sheets.shot.ready){k.save();k.translate(r.x,r.y);const u=this.game.units[r.id];k.rotate(Math.atan2(r.y-u.y,r.x-u.x));model(k,'shot',17,0,0,20,20,.5);k.restore();}};
})();
